/**
 * Merge the WhatsApp-derived aggregates into the Airtable-derived ones.
 *
 * The two sources describe the SAME activity in different periods: Airtable was
 * maintained until ~May 2026, then the initiative moved to the WhatsApp groups.
 * So they are summed into one combined figure — the dashboard presents a single
 * continuous history, not "old" and "new".
 *
 * This runs inside fetch_data.js, on purpose: data/*.json is regenerated by the
 * daily CI build, so merging at build time is the only way the WhatsApp numbers
 * survive the next deploy.
 *
 * WhatsApp records only where an item came FROM, so it contributes nothing to
 * flows.json (origin→destination) or to the "beneficiaries" count.
 */
const fs = require('fs');
const path = require('path');

const WA_DIR = path.join(__dirname, '..', 'data', 'whatsapp');
const round2 = (n) => Math.round(n * 100) / 100;

const readJson = (name) => {
  try { return JSON.parse(fs.readFileSync(path.join(WA_DIR, name), 'utf8')); }
  catch { return null; }
};

/** Sum a list of {name, ...} rows by name, adding the given numeric fields. */
function mergeByName(a = [], b = [], fields) {
  const out = new Map();
  [...a, ...b].forEach((row) => {
    const cur = out.get(row.name) || { name: row.name };
    fields.forEach((f) => { cur[f] = (cur[f] || 0) + (row[f] || 0); });
    out.set(row.name, cur);
  });
  return [...out.values()];
}

function mergeWhatsApp({ kpis, categories, topItems, weights, itemsTimeline }) {
  const wk = readJson('kpis.json');
  const wc = readJson('categories.json');
  const ww = readJson('weights.json');
  const wt = readJson('items-timeline.json');
  if (!wk) {
    console.log('↩︎ no WhatsApp aggregate found — Airtable data used as-is');
    return { kpis, categories, topItems, weights, itemsTimeline, merged: false };
  }

  // ---- kpis
  kpis.deliveries += wk.deliveries || 0;
  kpis.items += wk.items || 0;
  kpis.weightTon = round2((kpis.weightTon || 0) + (wk.weightTon || 0));
  // 'people' (beneficiaries) and flows have no WhatsApp equivalent — left as-is.

  Object.entries(wk.byCity || {}).forEach(([city, v]) => {
    const out = v.out || {};
    const entry = kpis.byCity[city] || (kpis.byCity[city] = {
      out: { deliveries: 0, people: 0, items: 0, weightTon: 0, partners: 0 },
      in: { deliveries: 0, people: 0, items: 0, weightTon: 0, partners: 0 },
    });
    entry.out.deliveries += out.deliveries || 0;
    entry.out.items += out.items || 0;
    entry.out.weightTon = round2((entry.out.weightTon || 0) + (out.weightTon || 0));
  });
  kpis.cities = Object.keys(kpis.byCity).length;
  kpis.sources = { airtable: true, whatsapp: true, whatsappPeriod: wk.period };

  // ---- categories + top items
  const mergedCats = mergeByName(categories, wc?.categories, ['count', 'weight'])
    .sort((a, b) => b.count - a.count);
  const mergedTop = mergeByName(topItems, wc?.topItems, ['count'])
    .sort((a, b) => b.count - a.count)
    .slice(0, 15);

  // ---- weights
  const mergedWeights = {
    totalTon: kpis.weightTon,
    byCategory: mergedCats.map((c) => ({ name: c.name, ton: round2(c.weight / 1000) })),
    byCity: mergeByName(weights.byCity, ww?.byCity, ['ton'])
      .map((c) => ({ name: c.name, ton: round2(c.ton) }))
      .sort((a, b) => b.ton - a.ton),
  };

  // ---- timeline: one continuous weekly series
  const weeks = new Map();
  [...(itemsTimeline.weeks || []), ...((wt && wt.weeks) || [])].forEach((w) => {
    const cur = weeks.get(w.week) || {};
    Object.entries(w.values || {}).forEach(([cat, n]) => { cur[cat] = (cur[cat] || 0) + n; });
    weeks.set(w.week, cur);
  });
  const mergedTimeline = {
    categories: [...new Set([...(itemsTimeline.categories || []), ...((wt && wt.categories) || [])])],
    weeks: [...weeks.keys()].sort().map((week) => ({ week, values: weeks.get(week) })),
  };

  console.log(`🔗 merged WhatsApp (${wk.period?.from}→${wk.period?.to}): `
    + `+${wk.deliveries} deliveries, +${wk.items} items, +${wk.weightTon} ton`);

  return {
    kpis,
    categories: mergedCats,
    topItems: mergedTop,
    weights: mergedWeights,
    itemsTimeline: mergedTimeline,
    merged: true,
  };
}

module.exports = { mergeWhatsApp };
